'use strict';

const os = require('os')
const path = require('path')
const { spawn } = require('child_process')

const CPU_PRIORITY = {
  LOW: os.constants.priority.PRIORITY_LOW,
  BELOW_NORMAL: os.constants.priority.PRIORITY_BELOW_NORMAL,
  NORMAL: os.constants.priority.PRIORITY_NORMAL,
  ABOVE_NORMAL: os.constants.priority.PRIORITY_ABOVE_NORMAL,
  HIGH: os.constants.priority.PRIORITY_HIGH,
}

const IO_PRIORITY = {
  LOW: 7,
  NORMAL: 4,
  HIGH: 0,
}

const which = (() => {
  try {
    return require('which');
  } catch (_) {
    return {
      sync: () => 'python3',
   }
  }
})();

const PY_DIR = path.join(__dirname, './smart_detect_analytics')
const PY_CMD = (() => {
  try {
    return which.sync('python3.9')
  } catch (_) {
    return 'python3'
  }
})();

const spawnPy = (py, options = {}) => {
  return new Promise((resolve, reject) => {
    const onError = (() => {
      let called = false
      return (err) => {
        if (called) return
        called = true
        reject(err)
      }
    })()

    let stdout = ''
    try {
      const pyFilepath = path.join(PY_DIR, py);
      const args = options.args || [];

      let {
        cpuPriority = CPU_PRIORITY.NORMAL,
        ioPriority = IO_PRIORITY.NORMAL
      } = options;

      // make sure cpu_priority between CPU_PRIORITY.LOW and CPU_PRIORITY.HIGH
      cpuPriority = Math.min(CPU_PRIORITY.LOW, Math.max(CPU_PRIORITY.HIGH, +cpuPriority))

      // make sure io_priority between IO_PRIORITY.LOW and IO_PRIORITY.HIGH
      ioPriority = Math.min(IO_PRIORITY.LOW, Math.max(IO_PRIORITY.HIGH, +ioPriority))

      const cmd = `${PY_CMD} ${pyFilepath} ${args.join(' ')}`
      const prioritizedCmd = `nice -n ${cpuPriority} ionice -t -c2 -n${ioPriority} sh -c "${cmd}"`
      const spawned = spawn(prioritizedCmd, {
        stdio: ['ignore', 'pipe', 'pipe'],
        shell: true
      });

      spawned.stdout.on('data', d => {
        stdout += d.toString();
      })
      spawned.on('error', onError)
      spawned.on('exit', (code, signal) => {
        if (code !== 0) {
          return onError(new Error(`${py} exited with code ${code}. (${prioritizedCmd})`))
        }
        resolve(stdout.trim().split('\n').filter(v => v))
      })
    } catch (err) {
      onError(err)
    }
  });
};

module.exports = {
  runPy: spawnPy,
  spawnPy,
  CPU_PRIORITY,
  IO_PRIORITY,
};
